package com.andye.warmod.radar.client.gui;
import com.andye.warmod.radar.client.*;import com.andye.warmod.radar.station.client.*;import java.util.*;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.Screen;import net.minecraft.client.input.*;import net.minecraft.network.chat.Component;import net.minecraft.world.phys.Vec3;
public final class RadarScreen extends Screen {private final RadarMapWidget map=new RadarMapWidget();private final ClientRadarState state=ClientRadarState.INSTANCE;private final ClientRadarStationState station=ClientRadarStationState.INSTANCE;private final RadarScreenMode mode;private int sidebarScroll;private boolean initializedMap,closing;private EditBox radiusField;public RadarScreen(){this(RadarScreenMode.GLOBAL);}public RadarScreen(RadarScreenMode mode){super(Component.literal(mode==RadarScreenMode.STATION?"Radar Station":"Missile Radar"));this.mode=mode;}@Override public boolean isPauseScreen(){return false;}@Override public boolean isInGameUi(){return true;}@Override public void tick(){double now=state.clock().now(0);if(mode==RadarScreenMode.STATION){station.prune(minecraft.level==null?0:minecraft.level.getGameTime());return;}state.pruneImpacts(now);ClientRadarTrack selected=state.selected();if(state.followSelectedTrack()&&selected!=null){Vec3 p=selected.position(now);map.transform().center(p.x,p.z);}}
 @Override protected void init(){if(!initializedMap){if(mode==RadarScreenMode.STATION&&station.centre()!=null){map.transform().center(station.centre().getX()+.5,station.centre().getZ()+.5);}else{centerPlayer();fitAll();}initializedMap=true;}if(mode==RadarScreenMode.STATION){int left=mapWidth()+12;int controlWidth=Math.max(100,sidebarWidth()-24);radiusField=new EditBox(font,left,134,controlWidth,18,Component.literal("Warning radius"));radiusField.setValue(Integer.toString((int)station.warningRadius()));radiusField.setMaxLength(4);addRenderableWidget(radiusField);addRenderableWidget(Button.builder(Component.literal("-16"),b->adjust(-16)).bounds(left,158,(controlWidth-6)/2,20).build());addRenderableWidget(Button.builder(Component.literal("+16"),b->adjust(16)).bounds(left+(controlWidth+6)/2,158,(controlWidth-6)/2,20).build());addRenderableWidget(Button.builder(Component.literal("Apply"),b->applyRadius()).bounds(left,182,controlWidth,20).build());}}
 private void adjust(int delta){try{radiusField.setValue(Integer.toString(Integer.parseInt(radiusField.getValue())+delta));}catch(NumberFormatException ignored){}}private void applyRadius(){try{ClientRadarStationNetworking.configure(Double.parseDouble(radiusField.getValue()));}catch(NumberFormatException ignored){}}
 @Override public void extractRenderState(GuiGraphicsExtractor g,int mouseX,int mouseY,float partial){int top=24,bottom=22,mapWidth=mapWidth(),mapHeight=Math.max(1,height-top-bottom),side=mapWidth;g.fill(0,0,width,height,0xff070b0d);if(mode==RadarScreenMode.STATION){double now=minecraft.level==null?0:minecraft.level.getGameTime()+partial;RadarMapRenderer.renderGrid(g,map.transform(),0,top,mapWidth,mapHeight);g.enableScissor(0,top,mapWidth,top+mapHeight);RadarSweepRenderer.render(g,station,map.transform(),now,0,top,mapWidth,mapHeight);g.disableScissor();g.fill(side,top,width,top+mapHeight,0xff0d1519);int x=side+12;g.text(font,Component.literal("RADAR STATION"),x,top+10,0xffffc45a);g.text(font,Component.literal(station.radarId()==null?"offline":station.radarId().toString().substring(0,8)),x,top+25,0xffc5d5dc);g.text(font,Component.literal("DETECTION RANGE"),x,top+46,0xff7f969d);g.text(font,Component.literal((int)station.detectionRange()+" blocks"),x,top+59,0xffffffff);g.text(font,Component.literal("WARNING RADIUS"),x,top+78,0xff7f969d);g.text(font,Component.literal((int)station.warningRadius()+" blocks"),x,top+91,0xffffffff);g.text(font,Component.literal("SWEEP PERIOD  "+String.format(Locale.ROOT,"%.1f s",station.sweepPeriod()/20.0)),x,top+188,0xffc5d5dc);g.text(font,Component.literal("CONTACTS  "+station.contacts()),x,top+202,0xffc5d5dc);g.text(font,Component.literal("THREATS   "+station.threats()),x,top+216,station.threats()>0?0xffff4b43:0xffc5d5dc);g.text(font,Component.literal("REDSTONE  "+(station.warningActive()?"ACTIVE":"CLEAR")),x,top+230,station.warningActive()?0xffff4b43:0xff8fd7a6);}else{double now=state.clock().now(partial);RadarMapRenderer.render(g,state,map.transform(),now,0,top,mapWidth,mapHeight);RadarSidebar.render(g,font,state,now,side,top,width-side,mapHeight,sidebarScroll);}g.fill(0,0,width,top,0xff11191d);g.text(font,Component.literal(mode==RadarScreenMode.STATION?"RADAR STATION SWEEP":"MISSILE RADAR"),8,8,0xffffc45a);String status=(mode==RadarScreenMode.STATION?(station.dimension()==null?"unknown":station.dimension().toString()):state.dimensionId()==null?"unknown":state.dimensionId().toString())+"   Scale: "+String.format(Locale.ROOT,"%.2f blocks/px",map.transform().blocksPerPixel())+"   Mode: "+(mode==RadarScreenMode.STATION?"Station Sweep":"Strategic Grid");g.text(font,Component.literal(status),150,8,0xffc5d5dc);g.fill(0,height-bottom,width,height,0xff11191d);g.text(font,Component.literal("Drag: Pan   Wheel: Zoom   "+(mode==RadarScreenMode.GLOBAL?"Click: Select   F: Follow   Home: Fit All   R: Centre Player   ":"")+"Esc: Close"),8,height-15,0xffa9bdc5);if(mode==RadarScreenMode.GLOBAL){ClientRadarTrack hovered=nearest(mouseX,mouseY,12);if(hovered!=null)RadarTooltip.render(g,font,hovered,mouseX,mouseY);}}
 @Override public boolean mouseClicked(MouseButtonEvent e,boolean dbl){int mw=mapWidth();if(map.contains(e.x(),e.y(),0,24,mw,height-46)&&e.button()==0){if(mode==RadarScreenMode.GLOBAL){ClientRadarTrack hit=nearest(e.x(),e.y(),12);if(hit!=null){state.select(hit.id());return true;}}map.beginDrag();return true;}return super.mouseClicked(e,dbl);}@Override public boolean mouseReleased(MouseButtonEvent e){map.endDrag();return super.mouseReleased(e);}@Override public boolean mouseDragged(MouseButtonEvent e,double dx,double dy){if(map.dragging()){map.transform().panPixels(dx,dy);state.disableFollow();return true;}return super.mouseDragged(e,dx,dy);}@Override public boolean mouseScrolled(double x,double y,double sx,double sy){int mw=mapWidth();if(map.contains(x,y,0,24,mw,height-46)){map.transform().zoomAt(sy,x,y,0,24,mw,height-46);state.disableFollow();return true;}sidebarScroll=Math.max(0,sidebarScroll-(int)(sy*18));return true;}@Override public boolean keyPressed(KeyEvent e){if(mode==RadarScreenMode.GLOBAL){if(e.key()==70){state.toggleFollow();return true;}if(e.key()==268){fitAll();return true;}if(e.key()==82){centerPlayer();return true;}}return super.keyPressed(e);}@Override public void removed(){if(!closing){closing=true;if(mode==RadarScreenMode.STATION)ClientRadarStationNetworking.close();else ClientRadarNetworking.close();}}
 private int sidebarWidth(){return Math.min(300,Math.max(220,(int)Math.round(width*.28)));}private int mapWidth(){return Math.max(1,width-sidebarWidth());}
 private void centerPlayer(){if(minecraft.player!=null){Vec3 p=minecraft.player.position();map.transform().center(p.x,p.z);}}private void fitAll(){if(mode!=RadarScreenMode.GLOBAL)return;int mw=mapWidth(),mh=Math.max(1,height-46);List<Vec3>points=new ArrayList<>();if(minecraft.player!=null)points.add(minecraft.player.position());for(ClientRadarTrack t:state.tracks()){points.add(t.launch());points.add(t.target());points.add(t.position(state.clock().now(0)));}for(ClientRadarImpact i:state.impacts())points.add(i.snapshot().impactPosition());if(points.isEmpty())return;map.transform().fit(points.stream().mapToDouble(p->p.x).min().orElse(0),points.stream().mapToDouble(p->p.z).min().orElse(0),points.stream().mapToDouble(p->p.x).max().orElse(0),points.stream().mapToDouble(p->p.z).max().orElse(0),mw,mh);}private ClientRadarTrack nearest(double x,double y,double radius){if(mode!=RadarScreenMode.GLOBAL)return null;int mw=mapWidth(),mh=height-46;ClientRadarTrack best=null;double bd=radius*radius,now=state.clock().now(0);for(ClientRadarTrack t:state.tracks()){Vec3 p=t.position(now);double dx=map.transform().screenX(p.x,0,mw)-x,dy=map.transform().screenY(p.z,24,mh)-y,d=dx*dx+dy*dy;if(d<bd){bd=d;best=t;}}return best;}}